() => {
  // Find all elements with 'keyboard' in their text
  const allElements = document.querySelectorAll('*');
  const keyboardElements = [];
  for (const el of allElements) {
    const text = el.textContent || '';
    if (text.toLowerCase().includes('keyboard') && text.length < 200) {
      keyboardElements.push({
        tag: el.tagName,
        text: text.substring(0, 150),
        className: el.className,
        id: el.id,
        isClickable: el.tagName === 'BUTTON' || el.tagName === 'A' || el.onclick !== null
      });
    }
  }
  return keyboardElements.slice(0, 20);
}

() => {
  // Find all elements with "Choose from 20 languages" in text
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    if (el.children.length === 0 && el.textContent.trim() === 'Choose from 20 languages') {
      // Find the closest clickable parent
      let parent = el;
      for (let i = 0; i < 5; i++) {
        parent = parent.parentElement;
        if (!parent) break;
        const style = window.getComputedStyle(parent);
        const isClickable = parent.tagName === 'BUTTON' || parent.tagName === 'A' || parent.onclick || style.cursor === 'pointer';
        if (isClickable) {
          return {
            found: true,
            text: parent.textContent.substring(0, 200),
            tag: parent.tagName,
            className: parent.className
          };
        }
      }
      return {
        found: false,
        parentText: parent ? parent.textContent.substring(0, 200) : 'none',
        parentTag: parent ? parent.tagName : 'none'
      };
    }
  }
  return { found: 'not_found' };
}

() => {
  // Find all elements containing "Choose from 20 languages"
  const allElements = document.querySelectorAll('*');
  const results = [];
  for (const el of allElements) {
    if (el.children.length === 0 && el.textContent.includes('Choose from 20 languages')) {
      // Walk up parents
      let parent = el;
      const path = [];
      for (let i = 0; i < 6; i++) {
        parent = parent.parentElement;
        if (!parent) break;
        path.push(parent.tagName + '.' + (parent.className ? parent.className.substring(0,30) : ''));
      }
      results.push({
        text: el.textContent.substring(0, 100),
        parentPath: path
      });
    }
  }
  return results;
}

() => {
  const results = [];
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    if (el.children.length === 0 && el.textContent.includes('Choose from 20 languages')) {
      // Walk up parents to find clickable element
      let parent = el;
      for (let i = 0; i < 8; i++) {
        parent = parent.parentElement;
        if (!parent) break;
        const isButton = parent.tagName === 'BUTTON';
        const isLink = parent.tagName === 'A';
        const hasOnclick = parent.getAttribute('onclick') !== null;
        const hasRole = parent.getAttribute('role') === 'button' || parent.getAttribute('role') === 'link';
        if (isButton || isLink || hasOnclick || hasRole) {
          results.push({
            foundAt: i,
            tag: parent.tagName,
            role: parent.getAttribute('role'),
            className: (parent.className || '').substring(0, 50),
            text: parent.textContent.substring(0, 100)
          });
          break;
        }
      }
    }
  }
  return results;
}

