() => {
  // Find element containing "Keyboard" text
  const allElements = document.querySelectorAll('h3, h2, div, button, span');
  let result = null;
  for (const el of allElements) {
    if (el.textContent.trim() === 'Keyboard') {
      let parent = el;
      for (let i = 0; i < 10; i++) {
        parent = parent.parentElement;
        if (!parent) break;
        if (parent.tagName === 'BUTTON' || parent.getAttribute('role') === 'button' || parent.onclick || parent.style.cursor === 'pointer') {
          result = {
            tag: parent.tagName,
            role: parent.getAttribute('role'),
            className: (parent.className || '').substring(0, 80),
            text: parent.textContent.substring(0, 150)
          };
          parent.click();
          return { clicked: true, info: result };
        }
      }
      return { clicked: false, keyboardParent: parent ? parent.tagName : 'none' };
    }
  }
  return result || 'keyboard_not_found';
}

() => {
  // Get all keyboard-related buttons and clickable elements
  const elements = Array.from(document.querySelectorAll('*'));
  const keyboardSection = [];
  for (const el of elements) {
    if (el.textContent && el.textContent.includes('Choose from 20 languages')) {
      // Get the parent accordion/container
      let parent = el;
      for (let i = 0; i < 15; i++) {
        parent = parent.parentElement;
        if (!parent) break;
        // Look for a clickable ancestor
        const style = window.getComputedStyle(parent);
        if (style.cursor === 'pointer' || parent.tagName === 'BUTTON' || parent.getAttribute('role') === 'button') {
          keyboardSection.push({
            depth: i,
            tag: parent.tagName,
            role: parent.getAttribute('role'),
            className: parent.className.substring(0, 60),
            cursor: style.cursor,
            hasOnClick: parent.onclick !== null
          });
        }
      }
    }
  }
  return keyboardSection.slice(0, 10);
}

() => {
  // Find all elements containing "Keyboard" exact text
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    if (el.children.length === 0 && el.textContent.trim() === 'Keyboard') {
      // Walk up to find clickable element
      let parent = el;
      const path = [];
      for (let i = 0; i < 15; i++) {
        parent = parent.parentElement;
        if (!parent) break;
        path.push(parent.tagName + '/' + (parent.className || '').substring(0, 40));
        // Check for button-like behavior
        const style = window.getComputedStyle(parent);
        if (style.cursor === 'pointer' || parent.tagName === 'BUTTON') {
          // Try to click it
          parent.click();
          return 'clicked at depth ' + i + ': ' + path.join(' < ');
        }
      }
      return 'no clickable found, path: ' + path.join(' < ');
    }
  }
  return 'not found';
}

